import React, { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import Isotope from "isotope-layout";
import imagesLoaded from "imagesloaded";
import "./css/MasonryDemo.css";
import getImgNames from "../../api/imgNames";
import { Container } from "react-bootstrap";
import LoadingState from "../../components/LoadingState";
import ErrorState from "../../components/ErrorState";

export default function PictureWall() {
  const [fileNames, setFileNames] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);
  const containerRef = useRef(null);

  //拉取图片列表:请求失败时进入降级态
  const load = useCallback(async () => {
    setLoading(true);
    setError(false);
    const res = await getImgNames();
    if (!Array.isArray(res)) {
      setLoading(false);
      setError(true);
      return;
    }
    setFileNames(res);
    setLoading(false);
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  // isotope 接管布局:列数由 CSS 媒体查询控制,
  // 跨断点/图片加载后重排时 isotope 自动平滑过渡
  useLayoutEffect(() => {
    const el = containerRef.current;
    if (!el || fileNames.length === 0) return undefined;

    const iso = new Isotope(el, {
      itemSelector: ".masonry-item",
      layoutMode: "masonry",
      masonry: { columnWidth: ".masonry-sizer", gutter: 20 },
      transitionDuration: "0.5s",
      isResizeBound: true,
    });
    let disposed = false;
    // 懒加载图片加载完成后重新布局
    imagesLoaded(el, () => {
      if (!disposed) iso.layout();
    });

    return () => {
      disposed = true;
      iso.destroy();
    };
  }, [fileNames]);

  if (loading) {
    return (
      <Container className="mt-3">
        <LoadingState />
      </Container>
    );
  }
  if (error) {
    return (
      <Container className="mt-3">
        <ErrorState onRetry={load} />
      </Container>
    );
  }
  return (
    <Container className="mt-3">
      <h1 className="text-center text-primary mb-4">生活图片墙</h1>
      {fileNames.length > 0 ? (
        <div className="masonry-container" ref={containerRef}>
          <div className="masonry-sizer" />
          {fileNames.map((image) => (
            <div key={image.id} className="masonry-item">
              <div className="masonry-item-inner">
                <img
                  src={`/images/${image.filename}`}
                  alt={image.alt}
                  className="masonry-image"
                  loading="lazy"
                />
              </div>
            </div>
          ))}
        </div>
      ) : (
        <h1 className="text-center text-primary">暂无图片</h1>
      )}
    </Container>
  );
}
