import React, { Component } from "react";
import { Container, ListGroup } from "react-bootstrap";
import getSubsidyList from "../../api/subsidy";
import LoadingState from "../../components/LoadingState";
import ErrorState from "../../components/ErrorState";

export default class Subsidy extends Component {
  state = { list: [], loading: true, error: false };

  //拉取补贴账单列表:请求失败时进入降级态
  fetchList = async () => {
    this.setState({ loading: true, error: false });
    const res = await getSubsidyList();
    if (!res || !res.data) {
      this.setState({ loading: false, error: true });
      return;
    }
    this.setState({ list: res.data.records, loading: false });
  };

  componentDidMount() {
    this.fetchList();
  }

  render() {
    const { list, loading, error } = this.state;
    if (loading) {
      return (
        <Container className="mt-3">
          <LoadingState />
        </Container>
      );
    }
    if (error) {
      return (
        <Container className="mt-3">
          <ErrorState onRetry={this.fetchList} />
        </Container>
      );
    }
    return (
      <Container className="mt-3 opacity-75">
        <ListGroup className="mb-3">
          {list.map((item) => {
            return (
              <ListGroup.Item as={"a"} key={item.id} action>
                <div className="d-flex w-100 justify-content-between">
                  <h3 className="mb-1 text-primary">补贴账单</h3>
                  <small className="fs-4 ">
                    金额:{""}
                    <span className="text-len-color">{item.amount}</span>
                  </small>
                </div>
                <p className="mb-1">时间: {item.issueTime}</p>
              </ListGroup.Item>
            );
          })}
        </ListGroup>
      </Container>
    );
  }
}
