import React, { Component, createRef } from "react";
import { Spinner } from "react-bootstrap";
import "./css/index.css";
import postUpload from "../../api/Upload";
export default class UploadPictures extends Component {
  state = { uploading: false };

  uploadFile = async () => {
    if (this.state.uploading) {
      return;
    }
    this.message.current.textContent = "";
    this.message.current.className = "";
    this.preview.current.innerHtml = "";

    if (this.fileInput.current.files.length === 0) {
      this.message.current.textContent = "请先选择一张图片！";
      this.message.current.className = "error";
      return;
    }
    const file = this.fileInput.current.files[0];
    const formData = new FormData();
    formData.append("DormPicture", file);
    this.setState({ uploading: true });
    const res = await postUpload(formData);
    if (res) {
      this.message.current.textContent = "上传成功！";
      this.message.current.className = "success";
      // 图片预览：用后端保存的路径拼接完整 URL
      const imgURL = "/images/" + res.filename;
      this.preview.current.innerHTML = `<img src="${imgURL}" alt="预览图片">`;
      this.fileInput.current.value = ""; // 清空文件选择框
    } else {
      this.message.current.textContent = "上传失败";
      this.message.current.className = "error";
    }
    this.setState({ uploading: false });
  };
  fileInput = createRef();
  message = createRef();
  preview = createRef();
  render() {
    const { uploading } = this.state;
    return (
      <div className="upload-container">
        <h2>{this.props.name}</h2>

        <div className="file-input-wrapper">
          <input
            type="file"
            className="upload"
            ref={this.fileInput}
            accept="image/*"
            aria-label="选择图片"
          />
        </div>

        <button className="upload" onClick={this.uploadFile} disabled={uploading}>
          {uploading ? (
            <>
              <Spinner
                as="span"
                animation="border"
                size="sm"
                className="me-2"
                aria-hidden="true"
              />
              上传中...
            </>
          ) : (
            "上传图片"
          )}
        </button>

        <div id="message" ref={this.message}></div>
        <div id="preview" ref={this.preview}></div>
      </div>
    );
  }
}
