import server from "./server";

const postUpload = async (FormData) => {
    try {
        const res = await server.post('/imgs/upload', FormData, {
            headers: {
                'Content-Type': 'multipart/form-data'
            }
        })
        return res.data
    } catch (e) {
        console.log('上传错误', e.message);
        return false
    }
}
export default postUpload