import React, { Component } from "react";
import { Container } from "react-bootstrap";
import Card from "react-bootstrap/Card";
import ListGroup from "react-bootstrap/ListGroup";
import getParticular from '../../api/particular'
import LoadingState from "../../components/LoadingState";
import ErrorState from "../../components/ErrorState";
export default class Detail extends Component {
  state={
    data:[],
    loading:true,
    error:false,
  }

  //拉取账单详情:请求失败时进入降级态
  fetchData = async () => {
    this.setState({ loading: true, error: false });
    const res = await getParticular(this.props.match.params.id)
    if (!res || !res.data) {
      this.setState({ loading: false, error: true })
      return
    }
    this.setState({ data: res.data, loading: false })
  }

  componentDidMount(){
    this.fetchData()
  }
  render() {
    const {data, loading, error } = this.state
    if (loading) {
      return (
        <Container className="mt-3">
          <LoadingState />
        </Container>
      )
    }
    if (error) {
      return (
        <Container className="mt-3">
          <ErrorState onRetry={this.fetchData} />
        </Container>
      )
    }
    return (
      <Container className="opacity-75 mt-3" style={{fontSize:'20px'}}>
        <Card border="primary">
          <Card.Header className="p-3" >消费金额:¥{data.consumeSum}-时长:{data.calculateTimeDiff}</Card.Header>
          <Card.Body>
            <ListGroup variant="flush">
              <ListGroup.Item>房间:{data.roomName}</ListGroup.Item>
              <ListGroup.Item>用电量:{data.consumeAmount}</ListGroup.Item>
              <ListGroup.Item>上一次读表数:{data.lastReportElectric}</ListGroup.Item>
              <ListGroup.Item>这一次读表数:{data.reportElectric}</ListGroup.Item>
              <ListGroup.Item>上一次的读表时间:{data.lastReportTime}</ListGroup.Item>
              <ListGroup.Item>这一次的读表时间:{data.reportTime}</ListGroup.Item>
              <ListGroup.Item>扣费时间:{data.consumeTime}</ListGroup.Item>
              <ListGroup.Item>交易状态:{data.statusName}</ListGroup.Item>
              <ListGroup.Item>消费方式:{data.consumeTypeName}</ListGroup.Item>
              <ListGroup.Item>消费渠道:{data.consumeChannelName}</ListGroup.Item>

            </ListGroup>
          </Card.Body>
        </Card>
      </Container>
    );
  }
}
