import React from "react";
import { Spinner } from "react-bootstrap";

// 数据加载中的占位状态:bootstrap Spinner(主题色)+ 文案
export default function LoadingState({ text = "加载中，请稍候…" }) {
  return (
    <div className="d-flex flex-column align-items-center justify-content-center py-5 text-center">
      <Spinner animation="border" variant="primary" role="status" aria-label={text} />
      <p className="mt-3 mb-0 text-body-secondary">{text}</p>
    </div>
  );
}
