import React, { useCallback, useEffect, useState } from "react";
import { Card, Container, ListGroup } from "react-bootstrap";
import getBillList from "../../api/BillList";
import getBalance from "../../api/balance";
import ConsumeAreaChart from "../../components/ConsumeAreaChart";
import LoadingState from "../../components/LoadingState";
import ErrorState from "../../components/ErrorState";

export default function ForecastApportion() {
  const [avg, setAvg] = useState(0);
  const [balance, setBalance] = useState(0);
  const [records, setRecords] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(false);

  //拉取近7日账单和余额:任一请求失败都进入降级态
  const load = useCallback(async () => {
    setLoading(true);
    setError(false);
    const res = await getBillList({ pageNumber: 1, pageSize: 7 });
    const resBalance = await getBalance();
    if (!res || !res.data || !resBalance || !resBalance.data) {
      setLoading(false);
      setError(true);
      return;
    }
    const newRecords = res.data.records;
    setBalance(resBalance.data.moneyBalance);
    setRecords(newRecords);
    const amount = newRecords.map((item) => {
      return item.list[0].consumeSum;
    });
    // 近7天没有账单时平均值为 0,避免出现 NaN
    setAvg(
      amount.length
        ? (amount.reduce((sum, current) => sum + current, 0) / amount.length).toFixed(2)
        : "0.00"
    );
    setLoading(false);
  }, []);

  useEffect(() => {
    load();
  }, [load]);

  if (loading) {
    return (
      <Container className="mt-3">
        <LoadingState />
      </Container>
    );
  }
  if (error) {
    return (
      <Container className="mt-3">
        <ErrorState onRetry={load} />
      </Container>
    );
  }
  return (
    <Container className="opacity-75 mt-3">
      <Card className="mb-3">
        <Card.Header>近7日电费消费</Card.Header>
        <Card.Body>
          <ConsumeAreaChart records={records} />
        </Card.Body>
      </Card>
      <ListGroup>
        <ListGroup.Item>当前账号剩余余额:{balance}</ListGroup.Item>
        <ListGroup.Item>最近七天的使用电费的平均值:{avg}</ListGroup.Item>
        <ListGroup.Item>明天的电费预测:{balance - avg}</ListGroup.Item>
      </ListGroup>
    </Container>
  );
}
