import React from "react";
import Container from "react-bootstrap/Container";
import Nav from "react-bootstrap/Nav";
import Navbar from "react-bootstrap/Navbar";
import Form from "react-bootstrap/Form";
import "./custom.css";
import { Link, NavLink } from "react-router-dom";
import { useEffect } from "react";

export default function Navigitor() {
  useEffect(() => {
    const isLight = window.matchMedia("(prefers-color-scheme: light)").matches;
    if (isLight) {
      const html = document.querySelector("html");
      html.setAttribute("data-bs-theme", "light");
    }
    console.log(isLight);
  }, []);
  function ToggleTheme(e) {
    if (e.target.checked) {
      const html = document.querySelector("html");
      html.setAttribute("data-bs-theme", "light");
    } else {
      const html = document.querySelector("html");
      html.setAttribute("data-bs-theme", "dark");
    }
  }
  return (
    <Navbar expand="lg" className="bg-body-tertiary">
      <Container>
        <Navbar.Brand as={Link} to="/index">
          4-135 宿舍管理系统
        </Navbar.Brand>
        <Navbar.Toggle aria-controls="basic-navbar-nav" />

        <Navbar.Collapse id="basic-navbar-nav">
          <Nav className="me-auto">
            <Nav.Link as={NavLink} to="/bill">
              账单
            </Nav.Link>
            <Nav.Link as={NavLink} to="/forecastApportion">
              电费预测+分摊
            </Nav.Link>
            <Nav.Link as={NavLink} to="/consumer">
              支付账单
            </Nav.Link>
            <Nav.Link as={NavLink} to="/subsidy">
              补贴账单
            </Nav.Link>
            <Nav.Link as={NavLink} to="/upload">
              图片上传
            </Nav.Link>
            <Nav.Link as={NavLink} to="/pictureWall">
              图片墙
            </Nav.Link>
          </Nav>
          <Form>
            <Form.Check // prettier-ignore
              type="switch"
              id="custom-switch"
              onChange={ToggleTheme}
            />
          </Form>
        </Navbar.Collapse>
      </Container>
    </Navbar>
  );
}
