import React, { useEffect, useState } from "react";
import ReactApexChart from "react-apexcharts";

// 主题色来自 App.scss :root 的 CSS 变量;jsdom 测试环境未加载样式表时兜底为字面量
function getMikuColor() {
  const fromRoot = getComputedStyle(document.documentElement)
    .getPropertyValue("--miku-color")
    .trim();
  return fromRoot || "#39c5bb";
}

function currentTheme() {
  return document.documentElement.getAttribute("data-bs-theme") === "dark"
    ? "dark"
    : "light";
}

// 接口返回新到旧的账单记录,转换为时间正序的图表数据 { x: 'MM-DD', y: 金额 }
export function buildSeriesData(records = []) {
  return records
    .map((record) => {
      const item = record.list[0];
      return { x: item.consumeTime.slice(5, 10), y: item.consumeSum };
    })
    .reverse();
}

export default function ConsumeAreaChart({ records }) {
  const [theme, setTheme] = useState(currentTheme);

  // 跟随页面右上角的明暗开关(html[data-bs-theme] 属性变化)
  useEffect(() => {
    const root = document.documentElement;
    const observer = new MutationObserver(() => setTheme(currentTheme()));
    observer.observe(root, { attributes: true, attributeFilter: ["data-bs-theme"] });
    return () => observer.disconnect();
  }, []);

  const isDark = theme === "dark";
  const options = {
    chart: {
      type: "area",
      background: "transparent",
      toolbar: { show: false },
      foreColor: isDark ? "#ced4da" : "#495057",
    },
    theme: { mode: theme },
    colors: [getMikuColor()],
    dataLabels: { enabled: false },
    stroke: { curve: "smooth", width: 2 },
    fill: {
      type: "gradient",
      gradient: { shadeIntensity: 1, opacityFrom: 0.4, opacityTo: 0.05, stops: [0, 90, 100] },
    },
    xaxis: { type: "category" },
    yaxis: { labels: { formatter: (value) => `¥${value.toFixed(2)}` } },
    tooltip: { y: { formatter: (value) => `¥${value.toFixed(2)}` } },
    grid: { borderColor: isDark ? "rgba(255,255,255,0.1)" : "rgba(0,0,0,0.08)" },
  };
  const series = [{ name: "消费金额", data: buildSeriesData(records) }];

  return (
    <ReactApexChart
      key={theme}
      options={options}
      series={series}
      type="area"
      height={300}
    />
  );
}
